public.fn_emit_management_content_event(.definition:
CREATE OR REPLACE FUNCTION public.fn_emit_management_content_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_club uuid; v_union uuid; v_type text; v_id uuid; v_role text := 'host';
  v_before jsonb; v_after jsonb;
BEGIN
  IF TG_TABLE_NAME = 'game_ticker_settings' THEN
    IF TG_OP = 'UPDATE'
       AND (to_jsonb(NEW) - ARRAY['updated_at','revision'])
           IS NOT DISTINCT FROM (to_jsonb(OLD) - ARRAY['updated_at','revision']) THEN
      RETURN NULL;
    END IF;
    v_club := COALESCE(NEW.club_id, OLD.club_id);
    v_union := COALESCE(NEW.union_id, OLD.union_id);
    v_type := 'ticker_settings_changed'; v_id := COALESCE(NEW.id, OLD.id);
    v_before := CASE WHEN TG_OP='INSERT' THEN NULL ELSE jsonb_build_object('settings',OLD.settings) END;
    v_after := CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object('settings',NEW.settings) END;
  ELSIF TG_TABLE_NAME = 'clubs' THEN
    IF NEW.tagline IS NOT DISTINCT FROM OLD.tagline
       AND NEW.lobby_message IS NOT DISTINCT FROM OLD.lobby_message
       AND NEW.description IS NOT DISTINCT FROM OLD.description THEN
      RETURN NULL;
    END IF;
    v_club := NEW.id; v_type := 'club_identity_changed'; v_id := NEW.id;
    v_before := jsonb_build_object('tagline',OLD.tagline,'lobby_message',OLD.lobby_message,'description',OLD.description);
    v_after := jsonb_build_object('tagline',NEW.tagline,'lobby_message',NEW.lobby_message,'description',NEW.description);
  ELSE
    IF TG_OP = 'UPDATE'
       AND (to_jsonb(NEW) - ARRAY['updated_at','management_revision'])
           IS NOT DISTINCT FROM (to_jsonb(OLD) - ARRAY['updated_at','management_revision']) THEN
      RETURN NULL;
    END IF;
    v_club := COALESCE(NEW.club_id,OLD.club_id);
    v_type := 'announcement_changed'; v_id := COALESCE(NEW.id,OLD.id);
    v_before := CASE WHEN TG_OP='INSERT' THEN NULL ELSE jsonb_build_object(
      'title',OLD.title,'content',OLD.content,'is_pinned',OLD.is_pinned,'is_active',OLD.is_active) END;
    v_after := CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object(
      'title',NEW.title,'content',NEW.content,'is_pinned',NEW.is_pinned,'is_active',NEW.is_active) END;
  END IF;

  PERFORM public.fn_emit_game_management_event(
    v_type,v_club,v_union,NULL,TG_TABLE_NAME,v_id,NULL,
    jsonb_build_object('operation',lower(TG_OP)));

  IF auth.uid() IS NOT NULL THEN
    IF v_union IS NOT NULL OR EXISTS (
      SELECT 1 FROM public.union_clubs WHERE club_id=v_club) THEN
      v_role := 'union_admin';
    ELSE
      SELECT CASE WHEN c.owner_id=auth.uid() THEN 'owner'
                  WHEN m.role='co_owner' THEN 'co_owner'
                  WHEN m.role='admin' THEN 'admin' ELSE 'host' END
        INTO v_role FROM public.clubs c
        LEFT JOIN public.club_members m
          ON m.club_id=c.id AND m.user_id=auth.uid()
       WHERE c.id=v_club;
    END IF;
    INSERT INTO public.audit_trail(
      actor_id,actor_role,action,target_type,target_id,club_id,before_state,after_state
    ) VALUES (
      auth.uid(),COALESCE(v_role,'host'),v_type,TG_TABLE_NAME,v_id,v_club,v_before,v_after);
  END IF;
  RETURN NULL;
END;
$function$

public.fn_club_owner_has_a_player_wallet.definition:
CREATE OR REPLACE FUNCTION public.fn_club_owner_has_a_player_wallet()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_previous text := COALESCE(current_setting('app.club_membership_source', true), '');
BEGIN
  IF NEW.owner_id IS NULL OR COALESCE(NEW.is_union, false) THEN RETURN NULL; END IF;
  IF TG_OP = 'UPDATE' AND OLD.owner_id IS NOT DISTINCT FROM NEW.owner_id THEN
    RETURN NULL;
  END IF;

  IF EXISTS (SELECT 1 FROM public.club_members cm
              WHERE cm.club_id = NEW.id AND cm.user_id = NEW.owner_id) THEN
    UPDATE public.club_members
       SET status = CASE WHEN COALESCE(status, 'active') IN ('active', 'approved') THEN status ELSE 'active' END,
           role   = CASE WHEN role IN ('owner', 'co_owner') THEN role ELSE 'owner' END,
           updated_at = now()
     WHERE club_id = NEW.id AND user_id = NEW.owner_id
       AND (COALESCE(status, 'active') NOT IN ('active', 'approved') OR role NOT IN ('owner', 'co_owner'));
    RETURN NULL;
  END IF;

  PERFORM set_config('app.club_membership_source', 'club_owner_create', true);
  PERFORM set_config('app.club_role_change', 'on', true);
  BEGIN
    INSERT INTO public.club_members (club_id, user_id, role, status, chip_balance)
    VALUES (NEW.id, NEW.owner_id, 'owner', 'active', 0)
    ON CONFLICT (club_id, user_id) DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.club_membership_source', v_previous, true);
    RAISE;
  END;
  PERFORM set_config('app.club_membership_source', v_previous, true);
  RETURN NULL;
END;
$function$

public.fn_clubs_lobby_message_keeps_its_.definition:
CREATE OR REPLACE FUNCTION public.fn_clubs_lobby_message_keeps_its_own_books()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Whitespace is not a message. One rule, applied before any writer's own.
  IF NEW.lobby_message IS NOT NULL AND btrim(NEW.lobby_message) = '' THEN
    NEW.lobby_message := NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.lobby_message_updated_at := CASE
      WHEN NEW.lobby_message IS NULL THEN NULL
      ELSE COALESCE(NEW.lobby_message_updated_at, now())
    END;
    RETURN NEW;
  END IF;

  IF NEW.lobby_message IS DISTINCT FROM OLD.lobby_message THEN
    NEW.lobby_message_updated_at := CASE
      WHEN NEW.lobby_message IS NULL THEN NULL
      ELSE now()
    END;
    -- A writer that bumped the revision in this same statement is left alone.
    -- One that forgot is corrected, which is the difference between a message
    -- rewritten from Club Settings reaching a player who dismissed the last
    -- one, and that message never reaching them at all.
    IF NEW.message_revision IS NOT DISTINCT FROM OLD.message_revision THEN
      NEW.message_revision := COALESCE(OLD.message_revision, 0) + 1;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

public.fn_guard_club_lifecycle_write().definition:
CREATE OR REPLACE FUNCTION public.fn_guard_club_lifecycle_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_retirement_write boolean :=
    coalesce(current_setting('app.club_retirement_write', true), '') = 'on';
  v_maintenance boolean :=
    auth.uid() IS NULL
    AND coalesce(current_setting('app.club_retirement_maintenance', true), '') = 'on';
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF NOT v_maintenance AND NOT (
      auth.uid() IS NULL
      AND (OLD.name LIKE 'Crest Cert %' OR OLD.name LIKE 'Preset Crest Cert %')
      AND coalesce(current_setting('app.ledger_maintenance', true), '') <> ''
      AND coalesce(current_setting('app.game_management_retention', true), '') = 'on'
    ) THEN
      RAISE EXCEPTION 'CLUB_RECORD_RETAINED: real club records cannot be deleted'
        USING ERRCODE = '55000';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.lifecycle_status = 'retired' AND NOT v_maintenance THEN
    RAISE EXCEPTION 'CLUB_RETIRED: this club is read-only'
      USING ERRCODE = '55000';
  END IF;

  IF (NEW.lifecycle_status, NEW.retired_at, NEW.retired_by, NEW.retirement_reason)
       IS DISTINCT FROM
     (OLD.lifecycle_status, OLD.retired_at, OLD.retired_by, OLD.retirement_reason)
     AND NOT v_retirement_write
     AND NOT v_maintenance THEN
    RAISE EXCEPTION 'CLUB_LIFECYCLE_REQUIRES_RPC: use fn_retire_settled_club'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END
$function$

public.fn_diamond_game_reserved_cover_gu.definition:
CREATE OR REPLACE FUNCTION public.fn_diamond_game_reserved_cover_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE host uuid; cover numeric; old_cover numeric; held numeric;
BEGIN
 IF TG_TABLE_NAME='clubs' THEN
  host:=NEW.id; cover:=GREATEST(COALESCE(NEW.promo_balance,0),0)+GREATEST(COALESCE(NEW.chip_treasury,0),0);
  old_cover:=GREATEST(COALESCE(OLD.promo_balance,0),0)+GREATEST(COALESCE(OLD.chip_treasury,0),0);
 ELSE
  host:=NEW.union_id; cover:=GREATEST(COALESCE(NEW.promo_wallet,0),0)+GREATEST(COALESCE(NEW.chip_balance,0),0);
  old_cover:=GREATEST(COALESCE(OLD.promo_wallet,0),0)+GREATEST(COALESCE(OLD.chip_balance,0),0);
 END IF;
 IF cover>=old_cover THEN RETURN NEW; END IF;
 SELECT COALESCE(sum(reserved_chips),0) INTO held FROM public.diamond_game_pools WHERE host_id=host;
 IF cover<held THEN RAISE EXCEPTION 'These Chips Are Reserved For Open Game Rounds'; END IF;
 RETURN NEW;
END $function$

public.fn_cash_cluster_epoch_follows_its.definition:
CREATE OR REPLACE FUNCTION public.fn_cash_cluster_epoch_follows_its_game()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.cash_cluster_epoch (cluster_id, epoch, mode, started_by, started_at)
    VALUES (NEW.id, NEW.cluster_epoch, NEW.cluster_mode, 'genesis', NEW.created_at)
    ON CONFLICT (cluster_id, epoch) DO NOTHING;
    IF FOUND THEN
      -- SPECIFICATION EVENT cluster_epoch_started (2026-09-26): the genesis epoch.
      INSERT INTO public.cash_cluster_events (game_id, kind, payload, cluster_epoch, request_id)
      VALUES (NEW.id, 'cluster_epoch_started', jsonb_build_object(
        'cluster_id', NEW.id, 'cluster_epoch', NEW.cluster_epoch, 'previous_epoch', NULL,
        'mode', NEW.cluster_mode, 'started_by', 'genesis', 'at', clock_timestamp()),
        NEW.cluster_epoch, CASE WHEN current_setting('ca.request_id', true) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             THEN current_setting('ca.request_id', true)::uuid END);
    END IF;
    RETURN NULL;
  END IF;

  IF NEW.cluster_epoch IS DISTINCT FROM OLD.cluster_epoch THEN
    IF NEW.cluster_epoch < OLD.cluster_epoch THEN
      RAISE EXCEPTION 'CLUSTER_EPOCH_GOES_FORWARD: cluster % cannot move from epoch % back to %',
        NEW.id, OLD.cluster_epoch, NEW.cluster_epoch
        USING ERRCODE = 'check_violation';
    END IF;
    UPDATE public.cash_cluster_epoch
       SET ended_at = clock_timestamp()
     WHERE cluster_id = NEW.id AND ended_at IS NULL;
    INSERT INTO public.cash_cluster_epoch (cluster_id, epoch, mode, started_by)
    VALUES (NEW.id, NEW.cluster_epoch, NEW.cluster_mode,
            coalesce(nullif(current_setting('ca.epoch_reason', true), ''), 'unstated'));
    -- SPECIFICATION EVENT cluster_epoch_started (2026-09-26).
    INSERT INTO public.cash_cluster_events (game_id, kind, payload, cluster_epoch, request_id)
    VALUES (NEW.id, 'cluster_epoch_started', jsonb_build_object(
      'cluster_id', NEW.id, 'cluster_epoch', NEW.cluster_epoch, 'previous_epoch', OLD.cluster_epoch,
      'mode', NEW.cluster_mode,
      'started_by', coalesce(nullif(current_setting('ca.epoch_reason', true), ''), 'unstated'),
      'at', clock_timestamp()),
      NEW.cluster_epoch, CASE WHEN current_setting('ca.request_id', true) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             THEN current_setting('ca.request_id', true)::uuid END);
    RETURN NULL;
  END IF;

  IF NEW.cluster_mode IS DISTINCT FROM OLD.cluster_mode THEN
    UPDATE public.cash_cluster_epoch
       SET mode = NEW.cluster_mode
     WHERE cluster_id = NEW.id AND ended_at IS NULL;
  END IF;
  RETURN NULL;
END;
$function$

public.generate_referral_code().definition:
CREATE OR REPLACE FUNCTION public.generate_referral_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    new_code VARCHAR(20);
    attempt integer;
BEGIN
    IF NEW.referral_code IS NOT NULL THEN
        RETURN NEW;
    END IF;
    FOR attempt IN 1..128 LOOP
        -- Compare the same representation that is stored and looked up by clients.
        new_code := UPPER('SP-' || SUBSTRING(MD5(RANDOM()::TEXT), 1, 6));
        IF EXISTS (SELECT 1 FROM public.profiles WHERE referral_code = new_code) THEN
            CONTINUE;
        END IF;
        -- An uncommitted generator owns this candidate. Skip it without waiting
        -- or accumulating a lock-order dependency between multi-row inserts.
        IF NOT pg_catalog.pg_try_advisory_xact_lock(
            pg_catalog.hashtextextended('profiles:referral-code:v1:' || new_code, 0)
        ) THEN
            CONTINUE;
        END IF;
        -- A previous owner may have committed between the first read and our lock.
        IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE referral_code = new_code) THEN
            NEW.referral_code := new_code;
            RETURN NEW;
        END IF;
    END LOOP;
    RAISE EXCEPTION USING ERRCODE = '54000',
        MESSAGE = 'Referral code generation exhausted its collision budget';
END;
$function$

public.fn_sync_mfa_required_on_role_chan.definition:
CREATE OR REPLACE FUNCTION public.fn_sync_mfa_required_on_role_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF (NEW.role = 'admin' OR NEW.is_vip = TRUE) AND NOT NEW.mfa_required THEN
        -- Only force the login challenge if the user can actually pass it.
        IF EXISTS (
            SELECT 1 FROM public.user_mfa_factors
            WHERE user_id = NEW.id AND enabled = TRUE
        ) THEN
            NEW.mfa_required := TRUE;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

public.fn_validate_home_url_fields().definition:
CREATE OR REPLACE FUNCTION public.fn_validate_home_url_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_arr_element text;
BEGIN
    -- Service role bypass
    IF auth.role() = 'service_role' THEN
        RETURN NEW;
    END IF;

    -- Route by table
    IF TG_TABLE_NAME = 'commander_home_games' THEN
        IF TG_OP = 'INSERT'
           OR NEW.cover_photo_url IS DISTINCT FROM OLD.cover_photo_url THEN
            IF public.fn_is_unsafe_url(NEW.cover_photo_url) THEN
                RAISE EXCEPTION 'unsafe cover_photo_url rejected: %', NEW.cover_photo_url
                      USING ERRCODE = '22023';
            END IF;
        END IF;

    ELSIF TG_TABLE_NAME = 'commander_home_game_photos' THEN
        IF TG_OP = 'INSERT'
           OR NEW.photo_url IS DISTINCT FROM OLD.photo_url THEN
            IF public.fn_is_unsafe_url(NEW.photo_url) THEN
                RAISE EXCEPTION 'unsafe photo_url rejected: %', NEW.photo_url
                      USING ERRCODE = '22023';
            END IF;
        END IF;

    ELSIF TG_TABLE_NAME = 'commander_home_groups' THEN
        IF TG_OP = 'INSERT'
           OR NEW.cover_photo_url IS DISTINCT FROM OLD.cover_photo_url THEN
            IF public.fn_is_unsafe_url(NEW.cover_photo_url) THEN
                RAISE EXCEPTION 'unsafe cover_photo_url rejected'
                      USING ERRCODE = '22023';
            END IF;
        END IF;
        IF TG_OP = 'INSERT'
           OR NEW.profile_photo_url IS DISTINCT FROM OLD.profile_photo_url THEN
            IF public.fn_is_unsafe_url(NEW.profile_photo_url) THEN
                RAISE EXCEPTION 'unsafe profile_photo_url rejected'
                      USING ERRCODE = '22023';
            END IF;
        END IF;
        IF TG_OP = 'INSERT'
           OR NEW.qr_code_url IS DISTINCT FROM OLD.qr_code_url THEN
            IF public.fn_is_unsafe_url(NEW.qr_code_url) THEN
                RAISE EXCEPTION 'unsafe qr_code_url rejected'
                      USING ERRCODE = '22023';
            END IF;
        END IF;

    ELSIF TG_TABLE_NAME = 'commander_home_posts' THEN
        IF TG_OP = 'INSERT'
           OR NEW.video_url IS DISTINCT FROM OLD.video_url THEN
            IF public.fn_is_unsafe_url(NEW.video_url) THEN
                RAISE EXCEPTION 'unsafe video_url rejected'
                      USING ERRCODE = '22023';
            END IF;
        END IF;
        -- image_urls is text[] - iterate on change.
        IF TG_OP = 'INSERT'
           OR NEW.image_urls IS DISTINCT FROM OLD.image_urls THEN
            IF NEW.image_urls IS NOT NULL THEN
                IF array_length(NEW.image_urls, 1) > 20 THEN
                    RAISE EXCEPTION 'too many image_urls (max 20)'
                          USING ERRCODE = '22023';
                END IF;
                FOREACH v_arr_element IN ARRAY NEW.image_urls LOOP
                    IF public.fn_is_unsafe_url(v_arr_element) THEN
                        RAISE EXCEPTION 'unsafe image_urls element rejected'
                              USING ERRCODE = '22023';
                    END IF;
                END LOOP;
            END IF;
        END IF;

    ELSIF TG_TABLE_NAME = 'profiles' THEN
        IF TG_OP = 'INSERT'
           OR NEW.avatar_url IS DISTINCT FROM OLD.avatar_url THEN
            IF public.fn_is_unsafe_url(NEW.avatar_url) THEN
                RAISE EXCEPTION 'unsafe avatar_url rejected'
                      USING ERRCODE = '22023';
            END IF;
        END IF;
        IF TG_OP = 'INSERT'
           OR NEW.cover_photo_url IS DISTINCT FROM OLD.cover_photo_url THEN
            IF public.fn_is_unsafe_url(NEW.cover_photo_url) THEN
                RAISE EXCEPTION 'unsafe cover_photo_url rejected'
                      USING ERRCODE = '22023';
            END IF;
        END IF;
        IF TG_OP = 'INSERT'
           OR NEW.hendon_url IS DISTINCT FROM OLD.hendon_url THEN
            IF public.fn_is_unsafe_url(NEW.hendon_url) THEN
                RAISE EXCEPTION 'unsafe hendon_url rejected'
                      USING ERRCODE = '22023';
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

public.fn_protect_profile_username_and_g.definition:
CREATE OR REPLACE FUNCTION public.fn_protect_profile_username_and_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing_id uuid;
BEGIN
  -- Trusted callers bypass entirely
  IF current_user IN ('postgres','service_role','supabase_admin','supabase_auth_admin') THEN
    RETURN NEW;
  END IF;

  -- Username validation: fires on INSERT (any non-empty username) or UPDATE
  -- when the username changed. All checks operate on the lowercase form so
  -- case-mixed inputs are validated correctly.
  IF TG_OP = 'INSERT' OR NEW.username IS DISTINCT FROM OLD.username THEN
    IF NEW.username IS NOT NULL AND btrim(NEW.username) <> '' THEN
      -- (1) Format
      IF lower(NEW.username) !~ '^[a-z0-9][a-z0-9_.]{2,19}$' THEN
        RAISE EXCEPTION 'Username Must Be 3-20 Characters Using Letters, Numbers, Underscores, Or Periods (No Spaces Or Special Characters).'
          USING ERRCODE = '22023';
      END IF;
      -- (2) Reserved words
      IF public.is_reserved_username(NEW.username) THEN
        RAISE EXCEPTION 'That Username Is Reserved. Pick A Different One.'
          USING ERRCODE = '22023';
      END IF;
      -- (3) Case-insensitive uniqueness - friendly message before the
      --     unique index can fire its raw 23505 error. Excludes self so a
      --     user resaving their own row (e.g. case-only change to OLD value)
      --     doesn't get rejected.
      SELECT id INTO v_existing_id FROM public.profiles
       WHERE lower(username) = lower(NEW.username)
         AND id <> NEW.id
       LIMIT 1;
      IF v_existing_id IS NOT NULL THEN
        RAISE EXCEPTION 'That Username Is Already Taken. Pick A Different One.'
          USING ERRCODE = '22023';
      END IF;
    END IF;
  END IF;

  -- Gate transition guard: false→true (or INSERT-with-true) requires all fields
  IF NEW.social_profile_completed = true 
     AND (TG_OP = 'INSERT' OR coalesce(OLD.social_profile_completed, false) = false) THEN
    IF coalesce(btrim(NEW.full_name), '') = '' THEN
      RAISE EXCEPTION 'Cannot Mark Profile Complete Without A Full Name.'
        USING ERRCODE = '22023';
    END IF;
    IF coalesce(btrim(NEW.username), '') = '' THEN
      RAISE EXCEPTION 'Cannot Mark Profile Complete Without A Username.'
        USING ERRCODE = '22023';
    END IF;
    IF length(regexp_replace(coalesce(NEW.phone, ''), '[^0-9]', '', 'g')) NOT BETWEEN 7 AND 15 THEN
      RAISE EXCEPTION 'Cannot Mark Profile Complete Without A Valid Phone Number (7-15 Digits).'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

public.fn_normalize_username().definition:
