public.fn_diamond_spin_wallet_reserve().definition:
CREATE OR REPLACE FUNCTION public.fn_diamond_spin_wallet_reserve()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE owed numeric;incoming numeric;
BEGIN
 IF TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM public.diamond_spin_days WHERE owner_id=OLD.id AND status='open') THEN
   RAISE EXCEPTION 'Settle Diamond Spins Before Removing This Wallet' USING ERRCODE='23514';
  END IF;
  RETURN OLD;
 END IF;
 SELECT COALESCE(sum(GREATEST(-pending_diamonds,0)),0),COALESCE(sum(GREATEST(pending_diamonds,0)),0)
  INTO owed,incoming FROM public.diamond_spin_days WHERE owner_id=NEW.id AND status='open';
 IF COALESCE(NEW.diamonds,0)<owed THEN
  RAISE EXCEPTION 'These Diamonds Back Unsettled Diamond Spin Prizes' USING ERRCODE='23514';
 END IF;
 IF COALESCE(NEW.diamonds,0)+incoming>2147483647 THEN
  RAISE EXCEPTION 'This Wallet Must Leave Room For Its Diamond Spin Settlement' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

public.fn_emit_union_owner_access_event(.definition:
CREATE OR REPLACE FUNCTION public.fn_emit_union_owner_access_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN
    PERFORM public.fn_emit_game_management_event(
      'management_access_changed',NULL,NEW.id,OLD.owner_id,'union',NEW.id,NULL,
      jsonb_build_object('operation','owner_changed')
    );
    PERFORM public.fn_emit_game_management_event(
      'management_access_changed',NULL,NEW.id,NEW.owner_id,'union',NEW.id,NULL,
      jsonb_build_object('operation','owner_changed')
    );
  END IF;
  RETURN NEW;
END;
$function$

public.fn_unions_set_slug().definition:
CREATE OR REPLACE FUNCTION public.fn_unions_set_slug()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_base text;
  v_slug text;
  v_n    integer := 1;
BEGIN
  v_base := public.fn_union_slugify(COALESCE(NULLIF(NEW.slug, ''), NEW.name));
  IF v_base IS NULL THEN
    v_base := 'union';
  END IF;
  -- A slug that parses as a UUID, or that is a route word, would be
  -- indistinguishable from the thing it stands beside.
  IF v_base ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR v_base IN ('create') THEN
    v_base := v_base || '-union';
  END IF;
  v_slug := v_base;
  WHILE EXISTS (SELECT 1 FROM public.unions u WHERE u.slug = v_slug AND u.id <> NEW.id) LOOP
    v_n := v_n + 1;
    v_slug := v_base || '-' || v_n;
  END LOOP;
  NEW.slug := v_slug;
  RETURN NEW;
END;
$function$

public.fn_terminal_credit_key_is_immutab.definition:
CREATE OR REPLACE FUNCTION public.fn_terminal_credit_key_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
  v_new_status text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.key IS DISTINCT FROM OLD.key THEN
    RAISE EXCEPTION 'wallet credit idempotency keys are immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' THEN
    v_old_tournament_id := public.fn_ca_tournament_id_from_credit_key(OLD.key);
  END IF;
  IF TG_OP <> 'DELETE' THEN
    v_new_tournament_id := public.fn_ca_tournament_id_from_credit_key(NEW.key);
  END IF;
  -- Recognized payout claims are append-only financial evidence. An existing
  -- row is already locked before this row trigger runs, so UPDATE/DELETE must
  -- refuse immediately instead of reversing the terminal root lock order.
  IF TG_OP <> 'INSERT'
     AND COALESCE(v_old_tournament_id,v_new_tournament_id) IS NOT NULL THEN
    RAISE EXCEPTION 'tournament wallet credit claims are append-only'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' AND v_new_tournament_id IS NOT NULL THEN
    SELECT upper(COALESCE(t.status::text,'')) INTO v_new_status
      FROM public.tournaments t
     WHERE t.id = v_new_tournament_id FOR SHARE;
    IF v_new_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
      RAISE EXCEPTION 'terminal wallet credit key evidence is immutable'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  IF v_new_tournament_id IS NOT NULL
     AND v_new_tournament_id IS DISTINCT FROM v_old_tournament_id THEN
    PERFORM 1 FROM public.tournaments t
     WHERE t.id = v_new_tournament_id FOR SHARE;
  END IF;
  IF public.fn_ca_has_committed_tournament_receipt(v_old_tournament_id)
     OR public.fn_ca_has_committed_tournament_receipt(v_new_tournament_id) THEN
    RAISE EXCEPTION 'terminal wallet credit key evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

public.fn_accounting_union_eco_capture().definition:
CREATE OR REPLACE FUNCTION public.fn_accounting_union_eco_capture()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE b jsonb; a jsonb; stamp timestamptz:=(public.fn_union_pnl_original_frame()).observed_at; moved boolean;
BEGIN
 b:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE public.fn_accounting_union_eco_terms(OLD.settings) END;
 a:=CASE WHEN TG_OP='DELETE' THEN NULL ELSE public.fn_accounting_union_eco_terms(NEW.settings) END;
 moved:=TG_OP='UPDATE' AND OLD.id IS DISTINCT FROM NEW.id;
 IF b IS NOT DISTINCT FROM a AND NOT moved THEN RETURN COALESCE(NEW,OLD); END IF;
 INSERT INTO public.accounting_agreement_history(entity_type,entity_key,union_id,club_id,event_type,
  observed_at,actor_id,before_terms,after_terms)
 VALUES('unions',CASE WHEN TG_OP='INSERT' THEN NEW.id ELSE OLD.id END::text,
  CASE WHEN TG_OP='INSERT' THEN NEW.id ELSE OLD.id END,NULL,CASE WHEN moved THEN 'DELETE' ELSE TG_OP END,
  stamp,auth.uid(),b,CASE WHEN moved THEN NULL ELSE a END);
 IF moved THEN
  INSERT INTO public.accounting_agreement_history(entity_type,entity_key,union_id,club_id,event_type,
   observed_at,actor_id,before_terms,after_terms)
  VALUES('unions',NEW.id::text,NEW.id,NULL,'INSERT',stamp,auth.uid(),NULL,a);
 END IF;
 RETURN COALESCE(NEW,OLD);
END $function$

public.fn_apply_prize_guarantee(uuid,tex.definition:
CREATE OR REPLACE FUNCTION public.fn_apply_prize_guarantee(p_tournament_id uuid, p_source text DEFAULT 'engine'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result jsonb;
  v_overlay numeric;
  v_ledger_count integer;
  v_escrow public.tournament_escrow%ROWTYPE;
BEGIN
  v_result:=public.fn_ca_apply_prize_guarantee_core(
    p_tournament_id,p_source);
  IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN v_result;
  END IF;
  v_overlay:=COALESCE((v_result->>'overlay')::numeric,0);
  IF v_overlay::text IN ('NaN','Infinity','-Infinity')
     OR v_overlay<0 OR v_overlay IS DISTINCT FROM round(v_overlay,2) THEN
    RAISE EXCEPTION 'guarantee core returned invalid overlay %',v_overlay
      USING ERRCODE='P0404';
  END IF;
  IF v_overlay>0 THEN
    SELECT count(*) INTO v_ledger_count
      FROM public.chip_ledger l
     WHERE l.idempotency_key=
             'tourney:'||p_tournament_id::text||':guarantee_overlay'
       AND l.tournament_id=p_tournament_id
       AND l.to_type='prize_liability'
       AND l.to_entity_id=p_tournament_id
       AND l.category='overlay'
       AND l.amount=v_overlay
       AND l.from_entity_id=(v_result->>'bank_entity_id')::uuid
       AND l.from_type=CASE WHEN v_result->>'bank_type'='union'
                            THEN 'union_bank' ELSE 'club_treasury' END;
    SELECT * INTO v_escrow
      FROM public.tournament_escrow e
     WHERE e.tournament_id=p_tournament_id
     FOR UPDATE;
    IF v_ledger_count<>1 OR NOT FOUND
       OR COALESCE(v_escrow.enforced,false) IS NOT TRUE
       OR v_result->>'escrow_after' IS NULL
       OR v_escrow.prize_balance IS DISTINCT FROM
            (v_result->>'escrow_after')::numeric THEN
      RAISE EXCEPTION
        'guarantee overlay is not one exact journaled escrow credit'
        USING ERRCODE='P0404';
    END IF;
  END IF;
  RETURN v_result||jsonb_build_object('overlay_journaled',true);
END;
$function$

public.fn_ca_lock_mtt_admission_contract.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_lock_mtt_admission_contract()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_abi text;
BEGIN
  SELECT abi INTO v_abi FROM public.ca_mtt_admission_contract WHERE singleton FOR SHARE;
  IF NOT FOUND OR v_abi NOT IN ('legacy-capacity-v1','unlimited-mtt-v2') THEN
    RAISE EXCEPTION 'MTT_ADMISSION_CONTRACT_MISSING_OR_UNKNOWN' USING ERRCODE='55000';
  END IF;
  RETURN v_abi;
END $function$

public.fn_ca_tournament_place_amounts(uu.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_tournament_place_amounts(p_tournament_id uuid)
 RETURNS TABLE(place integer, amount numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t record;
  v_pool numeric;
  v_ladder_pool numeric;
  v_bubble_amount numeric := 0;
  v_expected_pool numeric;
  v_pool_cents bigint;
  v_remaining bigint;
  v_share bigint;
  v_total_bp bigint := 0;
  v_bp bigint;
  v_field integer;
  v_struct jsonb;
  v_work jsonb := '[]'::jsonb;
  v_trimmed jsonb := '[]'::jsonb;
  v_entry jsonb;
  v_place_numeric numeric;
  v_pct numeric;
  v_place integer;
  v_valid boolean := true;
  v_is_spin boolean;
  v_known_spin boolean := false;
  v_count integer;
  v_max_place integer;
  v_index integer := 0;
BEGIN
  IF p_tournament_id IS NULL THEN
    RAISE EXCEPTION 'place amount derivation requires a tournament id'
      USING ERRCODE = '22004';
  END IF;

  SELECT t.id, t.prize_pool, t.payout_structure, t.variant,
         t.tournament_type, t.is_premium_spin, t.spin_multiplier,
         t.buy_in_amount, t.satellite_target_id, t.satellite_target,
         t.bubble_protection,t.payout_math_version,t.payout_unit_cents
    INTO v_t FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist', p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  IF lower(COALESCE(v_t.variant, '')) = 'satellite'
     OR upper(COALESCE(v_t.tournament_type, '')) = 'SATELLITE'
     OR v_t.satellite_target_id IS NOT NULL
     OR v_t.satellite_target IS NOT NULL THEN
    RAISE EXCEPTION 'tournament % is a satellite, not a cash ladder',
      p_tournament_id USING ERRCODE = '22023';
  END IF;

  IF v_t.payout_math_version=2 AND v_t.payout_unit_cents IS DISTINCT FROM public.fn_ca_tournament_unit_cents(p_tournament_id) THEN
    RAISE EXCEPTION 'Tournament denomination differs from its prize contract' USING ERRCODE='23514';
  END IF;
  v_pool := v_t.prize_pool;
  IF v_pool IS NULL
     OR v_pool::text IN ('NaN','Infinity','-Infinity')
     OR v_pool < 0
     OR v_pool IS DISTINCT FROM round(v_pool, 2) THEN
    RAISE EXCEPTION 'tournament % has invalid whole-cent prize pool %',
      p_tournament_id, v_pool USING ERRCODE = '22003';
  END IF;
  SELECT count(*) INTO v_field FROM public.tournament_players
   WHERE tournament_id = p_tournament_id;
  IF v_field < 1 THEN
    RAISE EXCEPTION 'tournament % has no roster', p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;

  v_is_spin := lower(COALESCE(v_t.variant, '')) = 'spin'
               OR COALESCE(v_t.is_premium_spin, false)
               OR upper(COALESCE(v_t.tournament_type, '')) = 'SPIN';
  IF v_is_spin THEN
    IF v_t.spin_multiplier IS NULL
       OR v_t.spin_multiplier::text IN ('NaN','Infinity','-Infinity')
       OR v_t.spin_multiplier <= 0
       OR v_t.buy_in_amount IS NULL
       OR v_t.buy_in_amount::text IN ('NaN','Infinity','-Infinity')
       OR v_t.buy_in_amount < 0
       OR v_t.buy_in_amount IS DISTINCT FROM round(v_t.buy_in_amount, 2) THEN
      RAISE EXCEPTION 'Spin % has invalid locked buy-in/multiplier evidence',
        p_tournament_id USING ERRCODE = '22003';
    END IF;
    v_expected_pool := round(v_t.buy_in_amount * v_t.spin_multiplier, 2);
    IF v_expected_pool::text IN ('NaN','Infinity','-Infinity')
       OR v_pool IS DISTINCT FROM v_expected_pool THEN
      RAISE EXCEPTION
        'Spin % pool % does not equal buy-in % x multiplier % (= %)',
        p_tournament_id, v_pool, v_t.buy_in_amount, v_t.spin_multiplier,
        v_expected_pool USING ERRCODE = '23514';
    END IF;

    IF v_t.spin_multiplier IN (2,3,4,5) THEN
      v_struct := '[{"place":1,"percentage":100}]'::jsonb;
      v_known_spin := true;
    ELSIF v_t.spin_multiplier = 10 THEN
      v_struct := '[{"place":1,"percentage":80},{"place":2,"percentage":20}]'::jsonb;
      v_known_spin := true;
    ELSIF v_t.spin_multiplier IN (25,50,100) THEN
      v_struct := '[{"place":1,"percentage":80},{"place":2,"percentage":12},{"place":3,"percentage":8}]'::jsonb;
      v_known_spin := true;
    END IF;
  END IF;

  -- Unknown/retired Spin multipliers and non-Spins read the stored structure.
  IF NOT v_known_spin THEN
    BEGIN
      v_struct := NULLIF(btrim(COALESCE(v_t.payout_structure::text, '')), '')::jsonb;
    EXCEPTION WHEN invalid_text_representation THEN
      v_struct := NULL;
    END;
  END IF;
  IF v_struct IS NULL OR jsonb_typeof(v_struct) <> 'array'
     OR jsonb_array_length(v_struct) = 0 THEN
    v_valid := false;
  END IF;

  -- Fractional places and non-finite/non-positive shares fail this candidate.
  -- As in computePlacePrize, the first entry for a duplicate place wins.
  IF v_valid THEN
    FOR v_entry IN SELECT value FROM jsonb_array_elements(v_struct) LOOP
      IF jsonb_typeof(v_entry) <> 'object'
         OR v_entry->>'place' IS NULL
         OR v_entry->>'percentage' IS NULL THEN
        v_valid := false; EXIT;
      END IF;
      BEGIN
        v_place_numeric := (v_entry->>'place')::numeric;
        v_pct := (v_entry->>'percentage')::numeric;
      EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        v_valid := false; EXIT;
      END;
      IF v_place_numeric::text IN ('NaN','Infinity','-Infinity')
         OR v_pct::text IN ('NaN','Infinity','-Infinity')
         OR v_place_numeric < 1 OR v_place_numeric <> trunc(v_place_numeric)
         OR v_place_numeric > 2147483647 OR v_pct <= 0 THEN
        v_valid := false; EXIT;
      END IF;
      IF v_t.payout_math_version=2 AND
         (v_pct>100 OR v_pct<>round(v_pct,2) OR EXISTS (
           SELECT 1 FROM jsonb_array_elements(v_work) e WHERE (e->>'place')::numeric=v_place_numeric
         )) THEN
        RAISE EXCEPTION 'Version 2 requires unique whole-hundredth payout shares' USING ERRCODE='22023';
      END IF;
      v_place := v_place_numeric::integer;
      IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_work) e
                  WHERE (e->>'place')::integer = v_place) THEN
        CONTINUE;
      END IF;
      BEGIN
        v_bp := round(v_pct * 100)::bigint;
      EXCEPTION WHEN numeric_value_out_of_range THEN
        v_valid := false; EXIT;
      END;
      IF v_bp <= 0 THEN
        v_valid := false; EXIT;
      END IF;
      v_work := v_work || jsonb_build_object('place',v_place,'bp',v_bp);
    END LOOP;
  END IF;
  IF v_valid AND NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_work) e
     WHERE (e->>'place')::integer = 1
  ) THEN
    v_valid := false;
  END IF;

  IF NOT v_valid THEN
    RAISE EXCEPTION
      'tournament % has no usable canonical payout ladder',
      p_tournament_id USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(jsonb_agg(e ORDER BY (e->>'place')::integer),'[]'::jsonb)
    INTO v_trimmed FROM jsonb_array_elements(v_work) e
   WHERE (e->>'place')::integer <= v_field;
  IF jsonb_array_length(v_trimmed) = 0 THEN
    RAISE EXCEPTION 'tournament % ladder has no place in final field %',
      p_tournament_id, v_field USING ERRCODE = '22023';
  END IF;
  SELECT count(*), COALESCE(sum((e->>'bp')::bigint),0)
    INTO v_count, v_total_bp FROM jsonb_array_elements(v_trimmed) e;
  IF v_total_bp <= 0 THEN
    RAISE EXCEPTION 'tournament % ladder has no positive percentage',
      p_tournament_id USING ERRCODE = '22023';
  END IF;

  SELECT max((e->>'place')::integer)
    INTO v_max_place
    FROM jsonb_array_elements(v_trimmed) e;

  -- Bubble protection is part of the tournament pool, not a house overlay.
  -- When the final field contains a stone bubble, reserve exactly one base
  -- buy-in before pricing the percentage ladder. The bubble and all places
  -- therefore spend the locked prize_pool exactly once between them.
  IF COALESCE(v_t.bubble_protection, false) AND v_field > v_max_place THEN
    IF v_t.buy_in_amount IS NULL
       OR v_t.buy_in_amount::text IN ('NaN','Infinity','-Infinity')
       OR v_t.buy_in_amount <= 0
       OR v_t.buy_in_amount IS DISTINCT FROM round(v_t.buy_in_amount, 2) THEN
      RAISE EXCEPTION
        'tournament % has bubble protection but invalid whole-cent buy-in %',
        p_tournament_id, v_t.buy_in_amount USING ERRCODE = '22003';
    END IF;
    v_bubble_amount := round(v_t.buy_in_amount, 2);
    IF v_bubble_amount > v_pool THEN
      RAISE EXCEPTION
        'tournament % bubble amount % exceeds locked prize pool %',
        p_tournament_id, v_bubble_amount, v_pool USING ERRCODE = '23514';
    END IF;
  END IF;

  v_ladder_pool := round(v_pool - v_bubble_amount, 2);
  v_pool_cents := round(v_ladder_pool * 100)::bigint;

  -- Mirror computePlacePrize: normalize to surviving basis points, spend down
  -- in place order, and give the exact remaining cents to the last place.
  v_remaining := v_pool_cents;
  FOR v_entry IN
    SELECT jsonb_build_object('place', l.place, 'cents', l.cents)
      FROM public.fn_ca_prize_ladder_versioned(
             v_pool_cents,
             v_trimmed,
             public.fn_ca_tournament_unit_cents(p_tournament_id),v_t.payout_math_version) l
     ORDER BY l.place
  LOOP
    v_index := v_index + 1;
    v_place := (v_entry->>'place')::integer;
    v_share := (v_entry->>'cents')::bigint;
    v_remaining := v_remaining - v_share;
    place := v_place;
    amount := (v_share::numeric / 100)::numeric(15,2);
    IF amount::text IN ('NaN','Infinity','-Infinity')
       OR amount < 0 OR amount IS DISTINCT FROM round(amount,2) THEN
      RAISE EXCEPTION 'derived invalid amount % for tournament %, place %',
        amount, p_tournament_id, place USING ERRCODE = '22003';
    END IF;
    RETURN NEXT;
  END LOOP;
  IF v_remaining <> 0 THEN
    RAISE EXCEPTION 'tournament % ladder left % cents undistributed',
      p_tournament_id, v_remaining USING ERRCODE = '23514';
  END IF;
END;
$function$

public.fn_ca_tournament_recorded_format(.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_tournament_recorded_format(p_tournament_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_format text;
BEGIN
  SELECT format_contract INTO v_format FROM public.tournaments WHERE id=p_tournament_id;
  IF NOT FOUND OR v_format IS NULL OR v_format NOT IN
     ('mtt-v1','mtt-v2','seat-first-satellite-v1','sng-v1','spin-v1') THEN
    RAISE EXCEPTION 'TOURNAMENT_FORMAT_NOT_PROVEN' USING ERRCODE='55000';
  END IF;
  RETURN v_format;
END $function$

public.fn_ca_apply_prize_guarantee_core(.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_apply_prize_guarantee_core(p_tournament_id uuid, p_source text DEFAULT 'engine'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t                    record;
  v_after                record;
  v_overlay_row          public.tournament_guarantee_overlays%ROWTYPE;
  v_result               jsonb;
  v_pool_before          numeric := 0;
  v_guarantee            numeric := 0;
  v_final                numeric := 0;
  v_overlay              numeric := 0;
  v_escrow_before        numeric := 0;
  v_escrow_after         numeric := 0;
  v_escrow_before_found  boolean := false;
  v_escrow_after_found   boolean := false;
  v_escrow_enforced      boolean := false;
  v_union                uuid;
  v_expected_bank_type   text;
  v_expected_bank_entity uuid;
  v_club_bank_before     numeric := 0;
  v_bank_before          numeric := 0;
  v_bank_after           numeric := 0;
  v_bank_row_found       boolean := false;
  v_ledger_inserted      integer := 0;
  v_old_category         text;
  v_old_counterparty     text;
  v_old_entity           text;
  v_old_tournament       text;
  v_failure              text;
  v_failure_state        text;
BEGIN
  IF p_tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_id_required',
                              'retryable', false);
  END IF;

  SELECT t.id, t.club_id, t.name, t.status, t.union_id,
         COALESCE(t.is_private, false) AS is_private,
         round(COALESCE(t.prize_pool, 0), 2) AS pool,
         round(COALESCE(t.guaranteed_prize, 0), 2) AS guarantee,
         COALESCE(t.prize_pool_finalized, false) AS finalized
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found',
                              'retryable', false);
  END IF;

  v_pool_before := v_t.pool;
  v_guarantee := v_t.guarantee;
  v_final := GREATEST(v_pool_before, v_guarantee);
  v_overlay := round(v_final - v_pool_before, 2);

  /* Finalized is irreversible. A published pool that was finalized below its
     guarantee is evidence requiring an explicit, reviewed correction; the
     runtime must never reopen and silently reprice it. */
  IF v_t.finalized AND v_pool_before + 0.005 < v_guarantee THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'finalized_guarantee_is_below_published_floor',
      'prize_pool', v_pool_before, 'guaranteed_prize', v_guarantee,
      'retryable', false);
  END IF;

  SELECT round(COALESCE(e.prize_balance, 0), 2)
    INTO v_escrow_before
    FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id
   FOR UPDATE;
  v_escrow_before_found := FOUND;

  BEGIN
    IF v_overlay > 0 THEN
      /* Lock and snapshot the real bank before calling the legacy debit core.
         Its overlay row describes the movement; only the live before/after
         balance proves that movement happened exactly once. */
      SELECT round(COALESCE(c.chip_treasury, 0), 2)
        INTO v_club_bank_before
        FROM public.clubs c
       WHERE c.id = v_t.club_id
       FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'guarantee host club does not exist',
                              ERRCODE = '23503';
      END IF;

      /* Funding ownership was captured on the event. A later club union move
         cannot redirect this liability, and a private event always belongs to
         its host club even when that club is currently union-affiliated. */
      v_union := CASE WHEN v_t.is_private THEN NULL ELSE v_t.union_id END;
      IF v_union IS NOT NULL THEN
        SELECT round(COALESCE(uw.chip_balance, 0), 2)
          INTO v_bank_before
          FROM public.union_wallets uw
         WHERE uw.union_id = v_union
         FOR UPDATE;
        v_bank_row_found := FOUND;
      END IF;
      IF v_bank_row_found THEN
        v_expected_bank_type := 'union';
        v_expected_bank_entity := v_union;
      ELSE
        v_expected_bank_type := 'club';
        v_expected_bank_entity := v_t.club_id;
        v_bank_before := v_club_bank_before;
      END IF;
      IF v_bank_before + 0.005 < v_overlay THEN
        RAISE EXCEPTION USING
          MESSAGE = format(
            'guarantee bank holds %s but the advertised overlay requires %s',
            v_bank_before, v_overlay),
          ERRCODE = '23514';
      END IF;
    END IF;

    v_old_category := current_setting('app.ledger_category', true);
    v_old_counterparty := current_setting('app.ledger_counterparty', true);
    v_old_entity := current_setting('app.ledger_counterparty_entity', true);
    v_old_tournament := current_setting('app.ledger_tournament', true);
    PERFORM set_config('app.ledger_tournament', p_tournament_id::text, true);

    v_result := public.fn_apply_prize_guarantee_before_atomic_proof(
      p_tournament_id, COALESCE(NULLIF(btrim(p_source), ''), 'engine'));
    IF NOT COALESCE((v_result->>'ok')::boolean, false) THEN
      RAISE EXCEPTION USING MESSAGE = COALESCE(v_result->>'reason', 'guarantee core refused'),
                            ERRCODE = '23514';
    END IF;
    IF v_overlay > 0 AND COALESCE((v_result->>'already_funded')::boolean, false) THEN
      RAISE EXCEPTION USING
        MESSAGE = 'an existing overlay claim did not prove this short pool was funded',
        ERRCODE = '23514';
    END IF;

    IF v_overlay > 0 THEN
      SELECT * INTO v_overlay_row
        FROM public.tournament_guarantee_overlays o
       WHERE o.tournament_id = p_tournament_id
       FOR UPDATE;
      IF NOT FOUND
         OR v_overlay_row.club_id IS DISTINCT FROM v_t.club_id
         OR abs(round(v_overlay_row.amount, 2) - v_overlay) > 0.005
         OR abs(round(v_overlay_row.pool_before, 2) - v_pool_before) > 0.005
         OR abs(round(v_overlay_row.pool_after, 2) - v_final) > 0.005
         OR v_overlay_row.bank_type IS DISTINCT FROM v_expected_bank_type
         OR v_overlay_row.bank_entity_id IS DISTINCT FROM v_expected_bank_entity
         OR v_overlay_row.treasury_after IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'guarantee overlay claim does not match its bank debit and pool',
                              ERRCODE = '23514';
      END IF;

      IF v_expected_bank_type = 'union' THEN
        SELECT round(COALESCE(uw.chip_balance, 0), 2)
          INTO v_bank_after
          FROM public.union_wallets uw
         WHERE uw.union_id = v_expected_bank_entity
         FOR UPDATE;
      ELSE
        SELECT round(COALESCE(c.chip_treasury, 0), 2)
          INTO v_bank_after
          FROM public.clubs c
         WHERE c.id = v_expected_bank_entity
         FOR UPDATE;
      END IF;
      IF NOT FOUND
         OR abs(v_bank_after - (v_bank_before - v_overlay)) > 0.005
         OR abs(round(v_overlay_row.treasury_after, 2) - v_bank_after) > 0.005 THEN
        RAISE EXCEPTION USING MESSAGE = 'guarantee bank did not debit the exact overlay',
                              ERRCODE = '23514';
      END IF;

      /* The legacy core's balance UPDATE produces an auto-ledger twin. Live
         escrow deliberately ignores auto-ledger overlay rows, so publish the
         one explicit, deterministic bank -> prize-liability leg it requires.
         This insert is in the same subtransaction as the bank debit. */
      INSERT INTO public.chip_ledger (
        performed_by, from_type, from_entity_id, to_type, to_entity_id,
        amount, category, club_id, tournament_id, idempotency_key, description)
      VALUES (
        COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
        CASE WHEN v_expected_bank_type = 'union' THEN 'union_bank' ELSE 'club_treasury' END,
        v_expected_bank_entity, 'prize_liability', p_tournament_id,
        v_overlay, 'overlay', v_t.club_id, p_tournament_id,
        'tourney:' || p_tournament_id::text || ':guarantee_overlay',
        'Guarantee Overlay Funded For ' || COALESCE(v_t.name, p_tournament_id::text))
      ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
      GET DIAGNOSTICS v_ledger_inserted = ROW_COUNT;
      IF v_ledger_inserted <> 1 THEN
        RAISE EXCEPTION USING MESSAGE = 'guarantee overlay journal key already exists unexpectedly',
                              ERRCODE = '23505';
      END IF;
    END IF;

    SELECT t.status, round(COALESCE(t.prize_pool, 0), 2) AS pool,
           round(COALESCE(t.guaranteed_prize, 0), 2) AS guarantee,
           COALESCE(t.prize_pool_finalized, false) AS finalized
      INTO v_after
      FROM public.tournaments t
     WHERE t.id = p_tournament_id
     FOR UPDATE;
    IF NOT FOUND OR NOT v_after.finalized
       OR abs(v_after.pool - v_final) > 0.005
       OR v_after.pool + 0.005 < v_after.guarantee THEN
      RAISE EXCEPTION USING MESSAGE = 'guarantee core did not publish the exact funded final pool',
                            ERRCODE = '23514';
    END IF;

    SELECT COALESCE(e.enforced, false), round(COALESCE(e.prize_balance, 0), 2)
      INTO v_escrow_enforced, v_escrow_after
      FROM public.tournament_escrow e
     WHERE e.tournament_id = p_tournament_id
     FOR UPDATE;
    v_escrow_after_found := FOUND;
    IF v_overlay > 0 AND (
         NOT v_escrow_after_found OR NOT v_escrow_enforced
         OR abs((v_escrow_after - CASE WHEN v_escrow_before_found
                                      THEN v_escrow_before ELSE 0 END) - v_overlay) > 0.005
       ) THEN
      RAISE EXCEPTION USING MESSAGE = 'guarantee bank debit did not credit live escrow exactly',
                            ERRCODE = '23514';
    END IF;

    PERFORM set_config('app.ledger_category', COALESCE(v_old_category, ''), true);
    PERFORM set_config('app.ledger_counterparty', COALESCE(v_old_counterparty, ''), true);
    PERFORM set_config('app.ledger_counterparty_entity', COALESCE(v_old_entity, ''), true);
    PERFORM set_config('app.ledger_tournament', COALESCE(v_old_tournament, ''), true);
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_failure = MESSAGE_TEXT,
                            v_failure_state = RETURNED_SQLSTATE;
  END;

  IF v_failure IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'atomic_guarantee_funding_aborted',
      'detail', v_failure, 'sqlstate', v_failure_state,
      'prize_pool', v_pool_before, 'guaranteed_prize', v_guarantee,
      'retryable', v_failure_state IN ('40001', '40P01', '55P03'));
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'prize_pool', v_after.pool,
    'overlay', v_overlay, 'bank_type', v_expected_bank_type,
    'bank_entity_id', v_expected_bank_entity,
    'bank_before', CASE WHEN v_overlay > 0 THEN v_bank_before ELSE NULL END,
    'bank_after', CASE WHEN v_overlay > 0 THEN v_bank_after ELSE NULL END,
    'treasury_after', CASE WHEN v_overlay > 0 THEN v_bank_after ELSE NULL END,
    'escrow_before', CASE WHEN v_escrow_before_found THEN v_escrow_before ELSE NULL END,
    'escrow_after', CASE WHEN v_escrow_after_found THEN v_escrow_after ELSE NULL END,
    'already_finalized', v_t.finalized AND v_overlay = 0,
    'retryable', false);
END;
$function$

public.fn_ca_prize_ladder_versioned(bigi.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_prize_ladder_versioned(p_pool_cents bigint, p_entries jsonb, p_unit_cents integer, p_version integer)
 RETURNS TABLE(place integer, cents bigint)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_version=1 THEN
    RETURN QUERY SELECT l.place,l.cents FROM public.fn_ca_prize_ladder(p_pool_cents,p_entries,p_unit_cents) l;
  ELSIF p_version=2 THEN
    RETURN QUERY SELECT l.place,l.cents FROM public.fn_ca_prize_ladder_v2(p_pool_cents,p_entries,p_unit_cents) l;
  ELSE
    RAISE EXCEPTION 'Unsupported tournament payout math version' USING ERRCODE='22023';
  END IF;
END;
$function$

public.fn_apply_prize_guarantee_before_a.definition:
CREATE OR REPLACE FUNCTION public.fn_apply_prize_guarantee_before_atomic_proof(p_tournament_id uuid, p_source text DEFAULT 'engine'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_t record; v_overlay numeric; v_final numeric; v_claimed integer;
  v_union uuid; v_bank_type text; v_bank_entity uuid;
  v_balance_after numeric; v_bank_name text; v_updated integer;
  v_note text := 'Guarantees are funded daily; union rake returns at the '
              || 'weekly rakeback close, so a mid-week dip is usually timing. '
              || 'Escalate if it survives a close.';
begin
  select t.id, t.club_id, t.name, t.union_id, coalesce(t.is_private, false) as is_private,
         coalesce(t.prize_pool, 0) as pool,
         coalesce(t.guaranteed_prize, 0) as gtd, coalesce(t.prize_pool_finalized, false) as finalized
    into v_t from public.tournaments t where t.id = p_tournament_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;

  if v_t.finalized then
    return jsonb_build_object('ok', true, 'already_finalized', true, 'prize_pool', v_t.pool);
  end if;

  v_final := greatest(v_t.pool, v_t.gtd);
  v_overlay := round(v_final - v_t.pool, 2);

  if v_overlay > 0 then
    -- ZERO-DRIFT phase 2: overlay funding = 'overlay' vs the tournament.
    perform set_config('app.ledger_category', 'overlay', true);
    perform set_config('app.ledger_counterparty', 'prize_liability', true);
    perform set_config('app.ledger_counterparty_entity', p_tournament_id::text, true);

    -- The event owns its funding scope, as in fn_ca_fund_overlay_on_lock.
    -- A club joining another union must not redirect this event's guarantee.
    v_union := CASE WHEN v_t.is_private THEN NULL ELSE v_t.union_id END;
    if v_union is not null then
      v_bank_type := 'union'; v_bank_entity := v_union;
    else
      v_bank_type := 'club'; v_bank_entity := v_t.club_id;
    end if;

    insert into public.tournament_guarantee_overlays
      (tournament_id, club_id, amount, pool_before, pool_after, source,
       bank_type, bank_entity_id, union_id)
    values (p_tournament_id, v_t.club_id, v_overlay, v_t.pool, v_final,
            coalesce(p_source, 'engine'), v_bank_type, v_bank_entity, v_union)
    on conflict (tournament_id) do nothing;
    get diagnostics v_claimed = row_count;

    if v_claimed = 0 then
      update public.tournaments set prize_pool_finalized = true where id = p_tournament_id;
      return jsonb_build_object('ok', true, 'already_funded', true, 'prize_pool', v_t.pool);
    end if;

    if v_bank_type = 'union' then
      update public.union_wallets
         set chip_balance = coalesce(chip_balance, 0) - v_overlay,
             updated_at = now()
       where union_id = v_union
       returning chip_balance into v_balance_after;

      if v_balance_after is null then
        update public.tournament_guarantee_overlays
           set bank_type = 'club', bank_entity_id = v_t.club_id
         where tournament_id = p_tournament_id;
        update public.clubs
           set chip_treasury = coalesce(chip_treasury, 0) - v_overlay, updated_at = now()
         where id = v_t.club_id
         returning chip_treasury into v_balance_after;
        v_bank_type := 'club'; v_bank_entity := v_t.club_id;
      else
        insert into public.union_wallet_transactions
          (union_id, wallet, direction, amount, balance_after, tx_type, club_id, notes)
        values
          (v_union, 'chip_balance', 'debit', v_overlay, v_balance_after,
           'guarantee_overlay', v_t.club_id,
           'Overlay for tournament ' || coalesce(v_t.name, p_tournament_id::text)
             || ' (' || p_tournament_id || '), pool ' || v_t.pool || ' -> ' || v_final);
      end if;
    else
      update public.clubs
         set chip_treasury = coalesce(chip_treasury, 0) - v_overlay, updated_at = now()
       where id = v_t.club_id
       returning chip_treasury into v_balance_after;
    end if;

    -- A missing bank must not manufacture an overlay or finalize the pool.
    -- RETURNING yields a non-null numeric balance after any actual debit,
    -- including the existing union-to-club fallback.
    if v_balance_after is null then
      raise exception 'guarantee_funding_bank_missing: tournament %, bank %/%',
        p_tournament_id, v_bank_type, v_bank_entity;
    end if;

    update public.tournament_guarantee_overlays
       set treasury_after = v_balance_after
     where tournament_id = p_tournament_id;

    select case when v_bank_type = 'union'
                then (select u.name from public.unions u where u.id = v_union)
                else (select c.name from public.clubs c where c.id = v_t.club_id) end
      into v_bank_name;

    if v_balance_after is not null and v_balance_after < 0 then
      update public.financial_alerts
         set severity = 'critical',
             message = 'Bank is negative from funding advertised guarantees: '
                       || coalesce(v_bank_name, v_bank_entity::text),
             context = jsonb_build_object(
                         'bank_type', v_bank_type,
                         'bank_entity_id', v_bank_entity,
                         'club_id', v_t.club_id,
                         'balance_after', v_balance_after,
                         'shortfall', round(-v_balance_after, 2),
                         'latest_tournament_id', p_tournament_id,
                         'latest_overlay', v_overlay,
                         'note', v_note),
             created_at = now()
       where source = 'fn_apply_prize_guarantee'
         and resolved is not true
         and context->>'bank_entity_id' = v_bank_entity::text;
      get diagnostics v_updated = row_count;

      if v_updated = 0 then
        insert into public.financial_alerts (severity, source, message, context)
        values ('critical', 'fn_apply_prize_guarantee',
                'Bank is negative from funding advertised guarantees: '
                  || coalesce(v_bank_name, v_bank_entity::text),
                jsonb_build_object(
                  'bank_type', v_bank_type,
                  'bank_entity_id', v_bank_entity,
                  'club_id', v_t.club_id,
                  'balance_after', v_balance_after,
                  'shortfall', round(-v_balance_after, 2),
                  'latest_tournament_id', p_tournament_id,
                  'latest_overlay', v_overlay,
                  'note', v_note));
      end if;
    end if;
  end if;

  update public.tournaments
     set prize_pool = v_final, prize_pool_finalized = true
   where id = p_tournament_id;

  return jsonb_build_object('ok', true, 'prize_pool', v_final,
    'overlay', coalesce(v_overlay, 0),
    'bank_type', v_bank_type, 'bank_entity_id', v_bank_entity,
    'treasury_after', v_balance_after);
end;
$function$

public.fn_ca_prize_ladder_v2(bigint,json.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_prize_ladder_v2(p_pool_cents bigint, p_entries jsonb, p_unit_cents integer)
 RETURNS TABLE(place integer, cents bigint)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_entry jsonb;
  v_place numeric;
  v_bp numeric;
  v_total numeric;
  v_units bigint;
BEGIN
  IF p_pool_cents IS NULL OR p_pool_cents<0
     OR p_unit_cents IS NULL OR p_unit_cents<1 THEN
    RAISE EXCEPTION 'Prize pool must contain whole payout units' USING ERRCODE='22023';
  END IF;
  IF p_pool_cents%p_unit_cents<>0 THEN
    RAISE EXCEPTION 'Prize pool must contain whole payout units' USING ERRCODE='22023';
  END IF;
  IF p_entries IS NULL OR jsonb_typeof(p_entries)<>'array'
     OR jsonb_array_length(p_entries)=0 THEN
    RAISE EXCEPTION 'Version 2 requires a canonical payout ladder' USING ERRCODE='22023';
  END IF;
  FOR v_entry IN SELECT value FROM jsonb_array_elements(p_entries) LOOP
    IF jsonb_typeof(v_entry)<>'object'
       OR jsonb_typeof(v_entry->'place') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_entry->'bp') IS DISTINCT FROM 'number' THEN
      RAISE EXCEPTION 'Canonical payout entries must contain numeric places and basis points'
        USING ERRCODE='22023';
    END IF;
    v_place:=(v_entry->>'place')::numeric;
    v_bp:=(v_entry->>'bp')::numeric;
    IF v_place<1 OR v_place>2147483647 OR v_place<>trunc(v_place)
       OR v_bp<=0 OR v_bp>10000 OR v_bp<>trunc(v_bp) THEN
      RAISE EXCEPTION 'Invalid canonical payout place or basis points' USING ERRCODE='22023';
    END IF;
  END LOOP;
  IF EXISTS (
    WITH entries AS (
      SELECT (e->>'place')::integer AS finish,(e->>'bp')::bigint AS bp
      FROM jsonb_array_elements(p_entries) e
    ), ranked AS (
      SELECT i.*,row_number() OVER(ORDER BY i.finish) AS ordinal,
        lag(i.bp) OVER(ORDER BY i.finish) AS prior_bp FROM entries i
    ) SELECT 1 FROM ranked r WHERE r.finish<>r.ordinal OR r.bp>r.prior_bp
  ) THEN
    RAISE EXCEPTION 'Version 2 requires contiguous places and nonincreasing percentages'
      USING ERRCODE='22023';
  END IF;
  IF p_pool_cents=0 THEN RETURN; END IF;
  SELECT sum((e->>'bp')::numeric) INTO v_total FROM jsonb_array_elements(p_entries) e;
  v_units:=p_pool_cents/p_unit_cents;
  RETURN QUERY
    WITH quotas AS (
      SELECT (e->>'place')::integer AS finish,
        floor(v_units::numeric*(e->>'bp')::numeric/v_total) AS units,
        mod(v_units::numeric*(e->>'bp')::numeric,v_total) AS remainder
      FROM jsonb_array_elements(p_entries) e
    ), ordered AS (
      SELECT q.*,row_number() OVER(ORDER BY q.remainder DESC,q.finish) AS priority
      FROM quotas q
    ), residual AS (SELECT v_units-sum(q.units) AS units FROM quotas q)
    SELECT q.finish,((q.units+CASE WHEN q.priority<=r.units THEN 1 ELSE 0 END)*p_unit_cents)::bigint
    FROM ordered q CROSS JOIN residual r ORDER BY q.finish;
END;
$function$

public.fn_ca_prize_ladder(bigint,jsonb,i.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_prize_ladder(p_pool_cents bigint, p_entries jsonb, p_unit_cents integer DEFAULT 1)
 RETURNS TABLE(place integer, cents bigint)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_unit bigint;
  v_total_bp bigint;
  v_count integer;
  v_places integer[];
  v_bps bigint[];
  v_remaining bigint;
  v_share bigint;
  i integer;
BEGIN
  v_unit := CASE WHEN p_unit_cents IS NOT NULL AND p_unit_cents >= 1
                 THEN p_unit_cents::bigint ELSE 1 END;
  IF p_pool_cents IS NULL OR p_pool_cents <= 0
     OR p_entries IS NULL OR jsonb_typeof(p_entries) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_entries) = 0 THEN
    RETURN;
  END IF;

  SELECT array_agg((e->>'place')::integer ORDER BY (e->>'place')::integer),
         array_agg((e->>'bp')::bigint ORDER BY (e->>'place')::integer),
         COALESCE(sum((e->>'bp')::bigint), 0),
         count(*)
    INTO v_places, v_bps, v_total_bp, v_count
    FROM jsonb_array_elements(p_entries) e;
  IF v_total_bp <= 0 OR v_count = 0 THEN RETURN; END IF;

  -- THE SHORT FIELD. A pool holding fewer units than there are places pays the
  -- places it CAN, one unit each from the top. Left alone, every share below
  -- rounds to zero and the last place absorbs the pool as its "residual": the
  -- whole prize to the last finisher and nothing to the first. An indivisible
  -- unit cannot be split nine ways, and every other answer pays somebody more
  -- than the player who beat them.
  IF v_unit > 1 AND (p_pool_cents / v_unit) < v_count THEN
    FOR i IN 1..v_count LOOP
      place := v_places[i];
      cents := CASE WHEN i <= (p_pool_cents / v_unit) THEN v_unit ELSE 0 END;
      RETURN NEXT;
    END LOOP;
    RETURN;
  END IF;

  -- Spend down in place order; the LAST paid place takes whatever remains, so
  -- the places sum to the pool exactly rather than by hoping the rounding
  -- cancels, and the adjustment lands on the smallest prize.
  v_remaining := p_pool_cents;
  FOR i IN 1..v_count LOOP
    IF i = v_count THEN
      v_share := v_remaining;
    ELSE
      v_share := LEAST(v_remaining,
        (round(round((p_pool_cents::numeric * v_bps[i]::numeric) / v_total_bp::numeric)
               / v_unit::numeric) * v_unit)::bigint);
    END IF;
    v_share := GREATEST(v_share, 0);
    v_remaining := v_remaining - v_share;
    place := v_places[i];
    cents := v_share;
    RETURN NEXT;
  END LOOP;

  IF v_remaining <> 0 THEN
    RAISE EXCEPTION 'prize ladder left % cents undistributed', v_remaining
      USING ERRCODE = '23514';
  END IF;
END;
$function$

public.fn_begin_tournament_launch_atomic.definition:
CREATE OR REPLACE FUNCTION public.fn_begin_tournament_launch_atomic(p_tournament_id uuid, p_launch_id uuid, p_started_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_format text;
  v_protocol_version integer;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(530090, 1);
  PERFORM public.fn_ca_lock_mtt_admission_contract();
  SELECT l.protocol_version INTO v_protocol_version
    FROM public.engine_tournament_leases l
   WHERE l.tournament_id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND OR v_protocol_version >= 2 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'legacy_launch_protocol_closed');
  END IF;
  v_format := public.fn_ca_tournament_recorded_format(p_tournament_id);
  IF v_format='mtt-v2' THEN
    RETURN jsonb_build_object('ok',false,'reason','launch_format_argument_required','format_contract',v_format);
  END IF;

  RETURN (public.fn_begin_tournament_launch_before_lease_generation(
    p_tournament_id,
    p_launch_id,
    p_started_at
  )) || jsonb_build_object('format_contract',v_format);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_begin_tournament_launch_atomic(p_tournament_id uuid, p_launch_id uuid, p_started_at timestamp with time zone, p_lease_generation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_format text;
  v_current_generation uuid;
  v_protocol_version integer;
  v_heartbeat_at timestamptz;
  v_receipt_generation uuid;
  v_result jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(530090, 1);
  PERFORM public.fn_ca_lock_mtt_admission_contract();

  IF p_tournament_id IS NULL OR p_launch_id IS NULL OR p_lease_generation IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_launch_request');
  END IF;

  SELECT l.lease_generation, l.protocol_version, l.heartbeat_at
    INTO v_current_generation, v_protocol_version, v_heartbeat_at
    FROM public.engine_tournament_leases l
   WHERE l.tournament_id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND
     OR v_protocol_version IS DISTINCT FROM 2
     OR v_current_generation IS DISTINCT FROM p_lease_generation
     OR v_heartbeat_at < clock_timestamp() - interval '30 seconds' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'launch_lease_lost');
  END IF;

  v_format := public.fn_ca_tournament_recorded_format(p_tournament_id);
  IF v_format='mtt-v2' THEN
    RETURN jsonb_build_object('ok',false,'reason','launch_format_argument_required','format_contract',v_format);
  END IF;

  v_result := public.fn_begin_tournament_launch_before_lease_generation(
    p_tournament_id,
    p_launch_id,
    p_started_at
  );

  IF COALESCE((v_result ->> 'ok')::boolean, false)
     AND NOT COALESCE((v_result ->> 'completed')::boolean, false) THEN
    SELECT r.lease_generation INTO STRICT v_receipt_generation
      FROM public.tournament_launch_receipts r
     WHERE r.tournament_id = p_tournament_id
     FOR UPDATE;
    IF v_receipt_generation IS DISTINCT FROM p_lease_generation THEN
      PERFORM set_config(
        'app.atomic_tournament_launch_lease_adoption',
        p_tournament_id::text || ':' || v_receipt_generation::text || ':' || p_lease_generation::text,
        true
      );
      UPDATE public.tournament_launch_receipts r
         SET lease_generation = p_lease_generation
       WHERE r.tournament_id = p_tournament_id
         AND r.completed_at IS NULL
         AND r.lease_generation = v_receipt_generation;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'tournament launch receipt changed during lease adoption'
          USING ERRCODE = '40001';
      END IF;
    END IF;
  END IF;

  RETURN v_result || jsonb_build_object('lease_generation', p_lease_generation,
    'format_contract', v_format);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_begin_tournament_launch_atomic(p_tournament_id uuid, p_launch_id uuid, p_started_at timestamp with time zone, p_lease_generation uuid, p_expected_format text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
